													case static_cast <uint8_t> (event::timer_t::SIMPLE):
														// Добавляем таймаут на ожидание записи данных
														::timer::simple::set({::timer::flag_t::SIMPLE, client->timeouts.write}, client->id, event::rate_t::DEFERRED, log);
