				// Если узел является клиентом
				case static_cast <uint8_t> (event::node_t::CLIENT):
					// Устанавливаем функцию обратного вызова для обработки таймаута события
					awh_cast <::io::client_t *> (i->second.get())->callbacks.timeout = ::move(cb);
				break;
